-- Read-only legacy-column preservation seal, captured from the actual Production catalog.
-- Compare before/after dormant install BEFORE creating any smoke fixtures.
-- New lifecycle columns are intentionally excluded; every existing column remains included.
begin transaction isolation level repeatable read read only;set local statement_timeout='20s';
select jsonb_build_object('observedAt',clock_timestamp(),'fingerprints',jsonb_build_object(
'budgets',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','trip_id','category','subcategory','title','amount','currency','exchange_rate','twd_amount','payer_id','split_type','is_fixed','auto_created_actual_expense_id','note','created_at','updated_at','locked_by','locked_at','pricing_mode','unit_amount'])) v from public.budget_items t) q),
'budgetParticipants',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','budget_item_id','user_id','created_at','share_amount'])) v from public.budget_item_participants t) q),
'actuals',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','trip_id','budget_item_id','title','amount','currency','exchange_rate','twd_amount','payer_id','paid_at','note','created_at','updated_at','locked_by','locked_at','budget_origin_id','category','subcategory','pricing_mode','split_type','unit_amount','twd_amount_source','actual_twd_amount','payment_origin','payment_active','payment_history'])) v from public.actual_expenses t) q),
'actualParticipants',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','actual_expense_id','user_id','created_at','share_amount'])) v from public.actual_expense_participants t) q),
'baselines',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.trip_id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['trip_id','departure_at','captured_at','payload'])) v from public.trip_budget_baselines t) q),
'attachments',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','trip_id','target_type','target_id','file_name','file_url','file_type','file_size','uploaded_by','created_at'])) v from public.attachments t) q),
'storageMetadata',(select encode(sha256(convert_to(coalesce(jsonb_agg(v order by row_id),'[]')::text,'UTF8')),'hex') from (select t.id row_id,(select jsonb_object_agg(k,x) from jsonb_each(to_jsonb(t)) e(k,x) where k=any(array['id','bucket_id','name','owner','created_at','updated_at','last_accessed_at','metadata','path_tokens','version','owner_id','user_metadata','archived_at','is_delete_marker','is_versioned'])) v from storage.objects t) q),
'tripRates',(select encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'rates',budget_exchange_rates) order by id),'[]')::text,'UTF8')),'hex') from public.trips)
)) preservation;
commit;
